// _codec_cloneSliceCodecWord returns a copy of x, a []codec.Word, and nil for a
// nil x.
func _codec_cloneSliceCodecWord(x []codec.Word) []codec.Word {
	if x == nil {
		return nil
	}
	c := make([]codec.Word, len(x))
	for k := range x {
		_codec_cloneCodecWord(&c[k], &x[k])
	}
	return c
}

// _codec_sizeCodecToken returns the length of the encoding of the codec.Token
// that x points at, and 1 when x fails to encode itself, so that the value is
// present and its encode reports the failure.
func _codec_sizeCodecToken(x *codec.Token) int {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 1
	}
	return len(enc)
}

