// _codec_cloneCodecWord copies the codec.Word that src points at into dst
// through its encode and decode methods, and by assignment when they fail.
func _codec_cloneCodecWord(dst, src *codec.Word) {
	*dst = *src
	enc, err := src.MarshalText()
	if err != nil {
		return
	}
	var c codec.Word
	if c.UnmarshalText(enc) == nil {
		*dst = c
	}
}
